    ) external view override returns (uint256[] memory) {
        uint256[] memory _balances = new uint256[](1);
        _balances[0] = uint256(1);
        return _balances;
    }

    /// @inheritdoc ITicket
    function getAverageBalanceBetween(
        address _user,
        uint64 _startTime,
        uint64 _endTime
    ) external view override returns (uint256) {
        return 1337;
    }
